ALTER TABLE content_entries ADD COLUMN canonical_vocabulary_id uuid REFERENCES content_entries(id);
CREATE TABLE vocabulary_notebooks (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id text NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80),description text NOT NULL DEFAULT '' CHECK(length(description)<=600),source_language text NOT NULL,target_language text NOT NULL,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(source_language<>target_language)
);
CREATE INDEX vocabulary_notebooks_owner ON vocabulary_notebooks(owner_id,updated_at DESC);
CREATE TABLE vocabulary_notebook_items (
 notebook_id uuid NOT NULL REFERENCES vocabulary_notebooks(id) ON DELETE CASCADE,entry_id uuid NOT NULL REFERENCES content_entries(id),added_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(notebook_id,entry_id)
);
ALTER TABLE learning_attempts ADD COLUMN notebook_id uuid REFERENCES vocabulary_notebooks(id) ON DELETE CASCADE;
ALTER TABLE learning_attempts ADD COLUMN practice_mode text NOT NULL DEFAULT 'writing' CHECK(practice_mode IN ('writing','flashcard'));
ALTER TABLE learning_attempts ADD COLUMN revealed_at timestamptz;
DROP INDEX content_entries_identity;
CREATE UNIQUE INDEX content_entries_identity ON content_entries(kind,lower(language),md5(content_phrase_key(phrase)),content_phrase_key(sense),(CASE WHEN kind='dialect' THEN coalesce(region_id,region) WHEN kind='situation' THEN coalesce(context_id,context) WHEN kind='attribution' THEN coalesce(challenge->>'category','') WHEN kind='false_friend' THEN coalesce(challenge->>'otherLanguage','') || ':' || content_phrase_key(coalesce(challenge->>'otherWord','')) WHEN kind='word_order' THEN coalesce(challenge->>'targetLanguage','') WHEN kind='vocabulary' THEN coalesce(challenge->'vocabulary'->>'translationLanguage','') ELSE '' END)) WHERE presentation<>'audio' AND deleted_at IS NULL;
DROP INDEX content_entries_audio_identity;
CREATE UNIQUE INDEX content_entries_audio_identity ON content_entries(kind,lower(language),audio_hash,content_phrase_key(sense),(CASE WHEN kind='dialect' THEN coalesce(region_id,region) WHEN kind='situation' THEN coalesce(context_id,context) WHEN kind='attribution' THEN coalesce(challenge->>'category','') WHEN kind='false_friend' THEN coalesce(challenge->>'otherLanguage','') || ':' || content_phrase_key(coalesce(challenge->>'otherWord','')) WHEN kind='word_order' THEN coalesce(challenge->>'targetLanguage','') WHEN kind='vocabulary' THEN coalesce(challenge->'vocabulary'->>'translationLanguage','') ELSE '' END)) WHERE audio_hash IS NOT NULL AND deleted_at IS NULL;
WITH pairs(canonical,mirror,en,de) AS (VALUES
 ('c4260000-0000-4000-8000-000000000001'::uuid,'c4260000-0000-4000-8000-000000000002'::uuid,'apple','der Apfel'),
 ('c4260000-0000-4000-8000-000000000003'::uuid,'c4260000-0000-4000-8000-000000000004'::uuid,'water','das Wasser'),
 ('c4260000-0000-4000-8000-000000000005'::uuid,'c4260000-0000-4000-8000-000000000006'::uuid,'bread','das Brot'),
 ('c4260000-0000-4000-8000-000000000007'::uuid,'c4260000-0000-4000-8000-000000000008'::uuid,'house','das Haus'),
 ('c4260000-0000-4000-8000-000000000009'::uuid,'c4260000-0000-4000-8000-000000000010'::uuid,'book','das Buch'),
 ('c4260000-0000-4000-8000-000000000011'::uuid,'c4260000-0000-4000-8000-000000000012'::uuid,'table','der Tisch'),
 ('c4260000-0000-4000-8000-000000000013'::uuid,'c4260000-0000-4000-8000-000000000014'::uuid,'train','der Zug'),
 ('c4260000-0000-4000-8000-000000000015'::uuid,'c4260000-0000-4000-8000-000000000016'::uuid,'friend','der Freund'),
 ('c4260000-0000-4000-8000-000000000017'::uuid,'c4260000-0000-4000-8000-000000000018'::uuid,'morning','der Morgen'),
 ('c4260000-0000-4000-8000-000000000019'::uuid,'c4260000-0000-4000-8000-000000000020'::uuid,'thank you','danke'))
UPDATE content_entries e SET challenge=jsonb_set(e.challenge,'{vocabulary}',jsonb_build_object('translationLanguage','de','translationExample',m.example,'reversible',true,'termAlternatives',coalesce((SELECT jsonb_agg(value) FROM jsonb_array_elements_text(e.challenge#>'{questions,0,answers}') a(value) WHERE value<>e.phrase),'[]'::jsonb),'translationAlternatives',coalesce((SELECT jsonb_agg(value) FROM jsonb_array_elements_text(m.challenge#>'{questions,0,answers}') a(value) WHERE value<>m.phrase),'[]'::jsonb),'context',CASE WHEN p.en='friend' THEN '{"de":"Gemeint ist eine männliche Person.","en":"This refers to a male person."}'::jsonb ELSE '{"de":"","en":""}'::jsonb END)),revision=e.revision+1,updated_at=now() FROM pairs p JOIN content_entries m ON m.id=p.mirror WHERE e.id=p.canonical AND e.kind='vocabulary' AND e.language='en' AND e.phrase=p.en AND e.literal=p.de AND e.revision=0 AND e.status='curated' AND e.author_id IS NULL AND m.kind='vocabulary' AND m.language='de' AND m.phrase=p.de AND m.literal=p.en AND m.revision=0 AND m.status='curated' AND m.author_id IS NULL AND e.deleted_at IS NULL AND m.deleted_at IS NULL;
UPDATE content_entries m SET canonical_vocabulary_id=e.id,revision=m.revision+1,updated_at=now() FROM content_entries e WHERE m.kind='vocabulary' AND m.language='de' AND m.phrase=e.literal AND m.literal=e.phrase AND m.revision=0 AND m.status='curated' AND m.author_id IS NULL AND m.id::text LIKE 'c4260000-0000-4000-8000-%' AND e.id::text LIKE 'c4260000-0000-4000-8000-%' AND e.challenge->'vocabulary'->>'translationLanguage'='de' AND m.deleted_at IS NULL;
CREATE UNIQUE INDEX content_vocabulary_pair_identity ON content_entries(least(lower(language),lower(challenge->'vocabulary'->>'translationLanguage')),greatest(lower(language),lower(challenge->'vocabulary'->>'translationLanguage')),md5(content_phrase_key(CASE WHEN language<challenge->'vocabulary'->>'translationLanguage' THEN phrase ELSE literal END)),md5(content_phrase_key(CASE WHEN language<challenge->'vocabulary'->>'translationLanguage' THEN literal ELSE phrase END)),content_phrase_key(sense)) WHERE kind='vocabulary' AND challenge->'vocabulary' IS NOT NULL AND deleted_at IS NULL;
INSERT INTO learning_progress(owner_id,entry_id,question_id,revision,streak,lapses,attempts,due_at,updated_at) SELECT p.owner_id,e.id,'vocab-en',e.revision,p.streak,p.lapses,p.attempts,p.due_at,p.updated_at FROM learning_progress p JOIN content_entries e ON e.id=p.entry_id WHERE p.question_id='recall' AND e.id::text LIKE 'c4260000-0000-4000-8000-%' AND e.challenge->'vocabulary'->>'translationLanguage'='de' AND p.revision=e.revision-1 ON CONFLICT DO NOTHING;
INSERT INTO learning_progress(owner_id,entry_id,question_id,revision,streak,lapses,attempts,due_at,updated_at) SELECT p.owner_id,e.id,'vocab-de',e.revision,p.streak,p.lapses,p.attempts,p.due_at,p.updated_at FROM learning_progress p JOIN content_entries m ON m.id=p.entry_id JOIN content_entries e ON e.id=m.canonical_vocabulary_id WHERE p.question_id='recall' AND p.revision=m.revision-1 ON CONFLICT DO NOTHING;
